import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  getAppointments,
  createAppointment,
  updateAppointment,
  deleteAppointment,
  getPatients,
  getProfessionals
} from '../services/api';
import './Pages.css';

export default function Appointments() {
  const [appointments, setAppointments] = useState([]);
  const [patients, setPatients] = useState([]);
  const [professionals, setProfessionals] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({
    patientId: '',
    professionalId: '',
    appointmentDate: '',
    appointmentTime: '',
    reason: '',
    status: 'scheduled'
  });

  useEffect(() => {
    fetchAppointments();
    fetchPatients();
    fetchProfessionals();
  }, []);

  const fetchAppointments = async () => {
    try {
      const res = await getAppointments();
      setAppointments(res.data);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const fetchPatients = async () => {
    try {
      const res = await getPatients();
      setPatients(res.data);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const fetchProfessionals = async () => {
    try {
      const res = await getProfessionals();
      setProfessionals(res.data);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const resetForm = () => {
    setEditing(null);
    setForm({
      patientId: '',
      professionalId: '',
      appointmentDate: '',
      appointmentTime: '',
      reason: '',
      status: 'scheduled'
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editing) {
        await updateAppointment(editing, form);
      } else {
        await createAppointment(form);
      }
      resetForm();
      setShowForm(false);
      fetchAppointments();
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleEdit = (appointment) => {
    setEditing(appointment.id);
    setForm({
      patientId: appointment.patientId,
      professionalId: appointment.professionalId || '',
      appointmentDate: appointment.appointmentDate,
      appointmentTime: appointment.appointmentTime,
      reason: appointment.reason,
      status: appointment.status
    });
    setShowForm(true);
  };

  const handleStatusChange = async (id, status) => {
    try {
      await updateAppointment(id, { status });
      fetchAppointments();
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const navigate = useNavigate();

  const handleDelete = async (id) => {
    if (window.confirm('¿Eliminar cita?')) {
      try {
        await deleteAppointment(id);
        fetchAppointments();
      } catch (err) {
        console.error('Error:', err);
      }
    }
  };

  const formatAppointmentDateTime = (appointmentDate, appointmentTime) => {
    if (!appointmentDate) return 'Fecha no disponible';

    let dateString;
    if (appointmentDate instanceof Date) {
      const year = appointmentDate.getFullYear();
      const month = String(appointmentDate.getMonth() + 1).padStart(2, '0');
      const day = String(appointmentDate.getDate()).padStart(2, '0');
      dateString = `${year}-${month}-${day}`;
    } else {
      dateString = String(appointmentDate);
    }

    const timeString = appointmentTime ? String(appointmentTime).trim() : '00:00';
    const isoString = `${dateString}T${timeString}`;
    const parsed = new Date(isoString);

    if (!Number.isNaN(parsed.getTime())) {
      return parsed.toLocaleString('es-ES', { dateStyle: 'short', timeStyle: 'short' });
    }

    const fallbackDate = new Date(dateString);
    if (!Number.isNaN(fallbackDate.getTime())) {
      return `${fallbackDate.toLocaleDateString('es-ES', { dateStyle: 'short' })} ${timeString}`;
    }

    return 'Fecha inválida';
  };

  return (
    <div className="page">
      <div className="page-header">
        <h2>📋 Citas</h2>
        <button onClick={() => { resetForm(); setShowForm(!showForm); }} className="btn-primary">
          {showForm ? 'Cancelar' : editing ? 'Editar Cita' : '+ Nueva Cita'}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="form-container">
          <div className="patient-select-row">
            <select
              value={form.patientId}
              onChange={(e) => setForm({ ...form, patientId: e.target.value })}
              required
            >
              <option value="">Selecciona paciente</option>
              {patients.map((p) => (
                <option key={p.id} value={p.id}>{p.firstName} {p.lastName}</option>
              ))}
            </select>
            <button
              type="button"
              className="btn-secondary"
              onClick={() => navigate('/patients')}
            >
              Registrar paciente
            </button>
          </div>
          <input
            type="date"
            value={form.appointmentDate}
            onChange={(e) => setForm({ ...form, appointmentDate: e.target.value })}
            required
          />
          <input
            type="time"
            value={form.appointmentTime}
            onChange={(e) => setForm({ ...form, appointmentTime: e.target.value })}
            required
          />
          <input
            type="text"
            placeholder="Razón"
            value={form.reason}
            onChange={(e) => setForm({ ...form, reason: e.target.value })}
            required
          />
          <select
            value={form.professionalId}
            onChange={(e) => setForm({ ...form, professionalId: e.target.value })}
          >
            <option value="">Selecciona profesional (opcional)</option>
            {professionals.map((p) => (
              <option key={p.id} value={p.id}>
                {p.firstName} {p.lastName} ({p.role})
              </option>
            ))}
          </select>
          <select
            value={form.status}
            onChange={(e) => setForm({ ...form, status: e.target.value })}
          >
            <option value="scheduled">Agendada</option>
            <option value="completed">Completada</option>
            <option value="cancelled">Cancelada</option>
          </select>
          <button type="submit" className="btn-success">
            {editing ? 'Actualizar' : 'Crear'}
          </button>
        </form>
      )}

      <table className="table">
        <thead>
          <tr>
            <th>Fecha / Hora</th>
            <th>Paciente</th>
            <th>Profesional</th>
            <th>Especialidad</th>
            <th>Estado</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {appointments.map((appointment) => (
            <tr key={appointment.id}>
              <td>{formatAppointmentDateTime(appointment.appointmentDate, appointment.appointmentTime)}</td>
              <td>{appointment.patientName} {appointment.patientLastName}</td>
              <td>{appointment.professionalFirstName ? `${appointment.professionalFirstName} ${appointment.professionalLastName}` : '-'}</td>
              <td>{appointment.professionalRole || '-'}</td>
              <td>
                <select
                  value={appointment.status}
                  onChange={(e) => handleStatusChange(appointment.id, e.target.value)}
                >
                  <option value="scheduled">Agendada</option>
                  <option value="completed">Completada</option>
                  <option value="cancelled">Cancelada</option>
                </select>
              </td>
              <td>
                <button className="btn-primary" onClick={() => handleEdit(appointment)}>Editar</button>
                <button className="btn-danger" onClick={() => handleDelete(appointment.id)}>Eliminar</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
